    "manual.highlights.accessBody": "Aplikasi memutuskan secara otomatis kapan harus meminta pendaftaran pengguna, pembuatan kata sandi, atau autentikasi biasa.",
    "manual.highlights.accessTitle": "Akses terpandu",
    "manual.highlights.locationBody": "Izin, akurasi GPS, dan pencatatan manual cadangan memengaruhi langsung alur pencatatan kehadiran.",
    "manual.highlights.locationTitle": "Lokasi terpantau",
    "manual.highlights.supportBody": "Pengaturan memusatkan bahasa, kata sandi, lokasi, dukungan melalui WhatsApp, dan akses ke dokumentasi ini.",
    "manual.highlights.supportTitle": "Bantuan cepat",
    "manual.introPrimary": "Manual ini merangkum alur utama autentikasi, pencatatan kehadiran, lokasi, transportasi, dan dukungan pada Checking Web.",
    "manual.introSecondary": "Gunakan halaman ini sebagai rujukan cepat untuk memahami apa yang dijalankan aplikasi secara otomatis dan tindakan mana yang tetap berada dalam kendali pengguna.",
    "manual.sections.accident.item1": "Setiap pengguna dapat membuka Mode Kecelakaan; ini memberi tahu, secara waktu nyata, semua pengguna pada proyek yang sama.",
    "manual.sections.accident.item2": "Laporkan kondisi dan zona Anda: aman, di lokasi kecelakaan tetapi aman, atau di lokasi kecelakaan dan butuh bantuan. Jika memungkinkan, rekam video lokasi: video dikirim secara waktu nyata ke panel administrator.",
    "manual.sections.accident.item3": "Tombol Hubungi Layanan Darurat menelepon layanan darurat setempat, melaporkan kecelakaan dan lokasi dalam bahasa wilayah tersebut.",
    "manual.sections.accident.lead": "Mode Kecelakaan adalah fitur keselamatan. Gunakan hanya dalam keadaan darurat nyata.",
    "manual.sections.accident.title": "Jika terjadi kecelakaan",
    "manual.sections.attendance.figureCaption": "Contoh keadaan berhasil setelah sebuah pencatatan kehadiran.",
    "manual.sections.attendance.item1": "Formulir membedakan check-in dari check-out dan dapat memblokir pengiriman manual saat aktivitas otomatis sedang mengendalikan alur.",
    "manual.sections.attendance.item2": "Riwayat yang terlihat di bagian atas membantu memastikan peristiwa terakhir yang tercatat sebelum mengirim peristiwa baru.",
    "manual.sections.attendance.item3": "Pesan keberhasilan atau kegagalan muncul di area status setelah setiap percobaan.",
    "manual.sections.attendance.lead": "Dengan autentikasi yang valid, pengguna memilih tipe pencatatan, meninjau konteks, dan mengirim operasi langsung dari layar utama.",
    "manual.sections.attendance.title": "Check-in dan check-out",
    "manual.sections.authFlow.item1": "Jika kunci tidak ada, alur beralih ke pendaftaran pengguna tanpa menunggu klik tambahan.",
    "manual.sections.authFlow.item2": "Jika kunci ada tetapi belum memiliki kata sandi, antarmuka langsung membuka pendaftaran kata sandi.",
    "manual.sections.authFlow.item3": "Jika kunci dan kata sandi sudah ada, antarmuka tetap berada pada jalur masuk normal.",
    "manual.sections.authFlow.lead": "Aplikasi memeriksa status kunci begitu kunci mencapai empat karakter yang valid dan menentukan alur bantuan mana yang ditampilkan.",
    "manual.sections.authFlow.note": "Menutup dialog secara manual tidak menimbulkan perulangan tanpa akhir: sistem hanya mencoba lagi saat kunci atau status autentikasi terkait benar-benar berubah.",
    "manual.sections.authFlow.title": "Alur autentikasi",
    "manual.sections.automaticActivities.item1": "Mekanisme ini bergantung pada autentikasi yang valid, pembacaan lokasi, dan aturan internal yang menghindari peralihan yang tidak aman.",
    "manual.sections.automaticActivities.item2": "Saat aktivitas otomatis mengendalikan alur, sebagian kolom manual menjadi tersembunyi atau dinonaktifkan untuk menjaga konsistensi catatan.",
    "manual.sections.automaticActivities.item3": "Jika akurasi turun di bawah ambang yang diperlukan, aplikasi dapat membuka kembali opsi pencatatan manual cadangan alih-alih mengambil keputusan berisiko.",
    "manual.sections.automaticActivities.lead": "Aplikasi juga dapat memicu check-in, check-out, dan pembaruan terkait saat konteks lokasi berubah sesuai harapan.",
    "manual.sections.automaticActivities.title": "Aktivitas otomatis",
    "manual.sections.faq.a1": "Ini terjadi saat kunci tidak ada atau saat akun masih belum memiliki kata sandi. Alur baru menghilangkan klik tambahan dan membawa pengguna langsung ke tindakan yang tepat.",
    "manual.sections.faq.a2": "Karena aplikasi sudah memahami bahwa izin presisi aktif, atau karena pembaruan lokasi sedang berjalan.",
    "manual.sections.faq.a3": "Pertama, pastikan kunci dan kata sandi telah terautentikasi. Jika masalah berlanjut, buka Dukungan agar kunci Anda dapat dikirim ke tim layanan.",
    "manual.sections.faq.lead": "Gunakan jawaban cepat ini saat antarmuka terasa macet atau saat alur tidak berlanjut seperti yang diharapkan.",
    "manual.sections.faq.q1": "Mengapa aplikasi membuka alur pendaftaran dengan sendirinya?",
    "manual.sections.faq.q2": "Mengapa tombol Izinkan Lokasi dinonaktifkan?",
    "manual.sections.faq.q3": "Apa yang harus dilakukan jika Transportasi tidak terbuka?",
    "manual.sections.faq.title": "Masalah umum dan FAQ",
    "manual.sections.location.figureCaptionDenied": "Contoh layar saat izin lokasi belum tersedia.",
    "manual.sections.location.figureCaptionGranted": "Contoh layar setelah akses lokasi presisi berhasil diberikan.",
    "manual.sections.location.item1": "Aplikasi bergantung pada HTTPS, dukungan peramban, dan izin aktif untuk mengakses lokasi presisi.",
    "manual.sections.location.item2": "Saat izin ditolak atau tidak tersedia, aplikasi menampilkan pesan yang jelas dan dapat membatasi alur pada pencatatan manual cadangan yang diizinkan.",
    "manual.sections.location.item3": "Saat lokasi berhasil diperoleh, antarmuka memperbarui akurasi, tempat yang dikenali, dan tindakan otomatis terkait.",
    "manual.sections.location.lead": "Posisi perangkat digunakan untuk menentukan konteks operasional, memicu alur otomatis, dan mengarahkan pengguna saat akurasi belum cukup.",
    "manual.sections.location.title": "Izin lokasi dan perilaku GPS",
    "manual.sections.login.item1": "Kata sandi dapat diverifikasi secara otomatis oleh alur yang sudah ada pada antarmuka utama.",
    "manual.sections.login.item2": "Jika pengguna mengubah kata sandi yang diketik setelah terautentikasi, aplikasi kembali melindungi diri hingga nilai baru diverifikasi lagi.",
    "manual.sections.login.item3": "Pesan status pada antarmuka membantu membedakan menunggu kata sandi, sedang memverifikasi, dan terautentikasi.",
    "manual.sections.login.lead": "Pengguna yang sudah terdaftar mengetik kunci, memasukkan kata sandi, dan membiarkan aplikasi memvalidasi autentikasi sebelum mencatat kehadiran atau membuka Transportasi.",
    "manual.sections.login.title": "Masuk",
    "manual.sections.overview.figureCaption": "Layar utama Checking Web dengan area autentikasi dan formulir pencatatan kehadiran.",
    "manual.sections.overview.item1": "Layar utama menampilkan kunci, kata sandi, riwayat terbaru, formulir pencatatan kehadiran, dan pintasan ke Transportasi.",
    "manual.sections.overview.item2": "Alur bantuan muncul secara otomatis saat kunci belum ada atau saat pengguna masih perlu membuat kata sandi pertama.",
    "manual.sections.overview.item3": "Menu Pengaturan mengelompokkan tindakan sekunder agar area utama tetap ringkas.",
    "manual.sections.overview.lead": "Checking Web menggabungkan autentikasi, pencatatan kehadiran, konteks lokasi, dan akses transportasi dalam satu antarmuka yang dioptimalkan untuk ponsel.",
    "manual.sections.overview.title": "Gambaran umum",
    "manual.sections.passwordChange.figureCaption": "Alur penggantian kata sandi yang dimulai dari Pengaturan > Ubah Kata Sandi.",
    "manual.sections.passwordChange.item1": "Buka Pengaturan, ketuk Ubah Kata Sandi, dan gunakan dialog penggantian kata sandi yang sudah ada.",
    "manual.sections.passwordChange.item2": "Alur meminta kata sandi lama, kata sandi baru, dan konfirmasi, dengan tetap mempertahankan validasi yang ada.",
    "manual.sections.passwordChange.item3": "Tombol hanya aktif saat pengguna sudah terautentikasi dan memiliki kata sandi terdaftar.",
    "manual.sections.passwordChange.lead": "Penggantian kata sandi tidak lagi berada pada baris autentikasi utama dan kini terpusat di Pengaturan.",
    "manual.sections.passwordChange.title": "Atur ulang atau ubah kata sandi",
    "manual.sections.passwordRegistration.figureCaption": "Dialog pembuatan kata sandi pertama untuk pengguna yang sudah dikenal sistem.",
    "manual.sections.passwordRegistration.item1": "Dialog menggunakan kembali komponen kata sandi yang ada, tetapi menyembunyikan kolom kata sandi lama.",
    "manual.sections.passwordRegistration.item2": "Pengguna memasukkan kata sandi baru, mengonfirmasi nilainya, dan menyelesaikan akses pertama.",
    "manual.sections.passwordRegistration.item3": "Setelah disimpan, backend mengautentikasi sesi web dan layar utama menerima operasi selebihnya.",
    "manual.sections.passwordRegistration.lead": "Jika kunci sudah ada tetapi belum ada kata sandi terdaftar, Checking Web masuk ke mode pembuatan kata sandi pertama.",
    "manual.sections.passwordRegistration.title": "Pendaftaran kata sandi otomatis",
    "manual.sections.projectSelection.figureCaption": "Contoh blok proyek dalam konteks terautentikasi, dengan ringkasan cakupan aktif.",
    "manual.sections.projectSelection.item1": "Pada pendaftaran, pengguna menandai satu atau beberapa proyek yang valid sebelum menyelesaikan pembuatan akun.",
    "manual.sections.projectSelection.item2": "Setelah terautentikasi, panel utama menampilkan proyek saat ini dan memungkinkan pembaruan ketika kemampuan itu tersedia.",
    "manual.sections.projectSelection.item3": "Proyek aktif memengaruhi daftar lokasi, riwayat kontekstual, dan area lain yang bergantung pada cakupan pengguna.",
    "manual.sections.projectSelection.lead": "Aplikasi menggunakan proyek baik pada pendaftaran awal maupun pada rutinitas harian, untuk membatasi konteks pengguna dan lokasi yang tersedia.",
    "manual.sections.projectSelection.title": "Pemilihan proyek",
    "manual.sections.scheduledPause.item1": "Di Pengaturan, ketuk Jeda Terjadwal.",
    "manual.sections.scheduledPause.item2": "Aktifkan opsi tersebut dan tetapkan waktu Dari dan Sampai (misalnya 22:00 hingga 06:00).",
    "manual.sections.scheduledPause.item3": "Jika mau, centang juga Jeda pada Sabtu dan/atau Jeda pada Minggu. Selama jeda, aplikasi tidak melakukan aktivitas otomatis apa pun dan melanjutkan sendiri di akhir periode.",
    "manual.sections.scheduledPause.lead": "Jeda Terjadwal menghemat baterai dengan menjeda aktivitas otomatis selama suatu periode (misalnya pada malam hari).",
    "manual.sections.scheduledPause.title": "Jeda Terjadwal",
    "manual.sections.settings.figureCaption": "Widget Pengaturan dengan tindakan sekunder baru yang terpusat.",
    "manual.sections.settings.item1": "Bahasa mengubah teks yang terlihat pada aplikasi utama dan menyimpan preferensi di peramban.",
    "manual.sections.settings.item2": "Izinkan Lokasi menggunakan kembali alur yang ada untuk meminta akses presisi sekali lagi saat hal itu masih diperlukan.",
    "manual.sections.settings.item3": "Dukungan dan Tentang menggunakan titik masuk yang sama untuk membuka WhatsApp dan dokumentasi ini.",
    "manual.sections.settings.lead": "Ikon roda gigi membuka titik pusat untuk preferensi dan tindakan sekunder, tanpa memenuhi baris autentikasi.",
    "manual.sections.settings.title": "Pengaturan",
    "manual.sections.support.item1": "Tautan menggunakan nomor telepon resmi yang dikonfigurasi pada frontend Checking Web.",
    "manual.sections.support.item2": "Pesan awal disiapkan secara otomatis untuk mengurangi hambatan dan mempercepat layanan.",
    "manual.sections.support.item3": "Jika tidak ada kunci valid yang tersedia, tombol dukungan tetap dinonaktifkan demi keamanan.",
    "manual.sections.support.lead": "Saat pengguna butuh bantuan manusia, Pengaturan > Dukungan menyiapkan percakapan WhatsApp dengan kunci pengguna yang sudah disertakan pada pesan pertama.",
    "manual.sections.support.title": "Dukungan",
    "manual.sections.transport.figureCaption": "Contoh antarmuka Transportasi yang diakses dari antarmuka Checking Web.",
    "manual.sections.transport.item1": "Akses tetap terlindungi oleh kunci dan kata sandi yang sama yang divalidasi pada antarmuka utama.",
    "manual.sections.transport.item2": "Modul ini mencakup pendaftaran alamat, permintaan per tipe transportasi, dan ringkasan status saat ini.",
    "manual.sections.transport.item3": "Saat ada kendaraan yang dialokasikan, layar menampilkan detail operasional utama bagi pengguna.",
    "manual.sections.transport.lead": "Setelah autentikasi, pengguna dapat membuka modul Transportasi untuk meminta perjalanan, memeriksa status, dan meninjau detail permintaan terbaru.",
    "manual.sections.transport.title": "Akses Transportasi",
    "manual.sections.userRegistration.figureCaption": "Dialog pendaftaran pengguna baru yang terbuka otomatis untuk kunci yang belum dikenal.",
    "manual.sections.userRegistration.item1": "Formulir meminta kunci, nama lengkap, proyek, email opsional, kata sandi, dan konfirmasi kata sandi.",
    "manual.sections.userRegistration.item2": "Proyek dimuat dari API dan pengguna dapat menandai satu atau beberapa item yang valid.",
    "manual.sections.userRegistration.item3": "Setelah pengiriman berhasil, sesi web terautentikasi dan aplikasi tetap terbuka untuk digunakan.",
    "manual.sections.userRegistration.lead": "Saat kunci tidak ada di basis data, aplikasi membuka formulir layanan mandiri agar pengguna baru dapat menyelesaikan pendaftaran.",
    "manual.sections.userRegistration.title": "Pendaftaran pengguna otomatis",
